import React from 'react'; 

// Sample product data 
const products = [ 
  { pid: 'P001', pname: 'Product 1', price: '$10' ,pcategory: 'Cat1', dateoManf: '06/01/2025',pquantity: '1'}, 
  { pid: 'P002', pname: 'Product 2', price: '$20', pcategory: 'Cat2' ,dateoManf: '07/01/2025',pquantity: '1'}, 
  { pid: 'P003', pname: 'Product 3', price: '$30' ,pcategory: 'Cat3' ,dateoManf: '08/01/2025',pquantity: '1'}, 
  { pid: 'P004', pname: 'Product 4', price: '$40', pcategory: 'Cat4' ,dateoManf: '09/01/2025',pquantity: '1'},
  { pid: 'P005', pname: 'Product 5', price: '$50' ,pcategory: 'Cat5' ,dateoManf: '10/01/2025',pquantity: '1'}


]; 


const Products = () => { 
  return ( 
    <div> 
      <h1>Products List</h1> 

      <table> 

        <thead> 
          <tr> 
            <th>Product ID</th> 
            <th>Product Name</th> 
            <th>Price</th> 
            <th>Category</th>
            <th>DateofManf</th>
            <th>Quantity</th>

          </tr> 
        </thead> 


        <tbody> 
          {products.map(product => ( 
            <tr key={product.pid}> 
              <td>{product.pid}</td> 
              <td>{product.pname}</td> 
              <td>{product.price}</td> 
              <td>{product.p} </td>
              <td>{product.pid}</td>
              <td>{product.pid}</td>
            </tr> 
          ))} 
        </tbody> 

      </table> 

    </div> 
  ); 
}; 

export default Products;
